"""A small PTY-backed interactive terminal for driving shell sessions."""

from __future__ import annotations

import os
import pty
import select
import signal
import subprocess
import termios
import threading
import time
from typing import Optional

from base_terminal import BaseTerminal


class HeadlessTerminal(BaseTerminal):
    """Run an interactive Bash shell and send terminal input to it.

    Output is drained continuously so programs cannot block on a full PTY
    buffer. Use :meth:`get_output` to read output produced since the previous
    call. ``send_keystrokes`` writes input immediately and optionally waits for
    the given number of seconds while output continues to be collected.
    """

    def __init__(self, cwd: Optional[str] = None, env: Optional[dict[str, str]] = None):
        self._master_fd, slave_fd = pty.openpty()
        # A useful default terminal size for readline and full-screen programs.
        size = (24).to_bytes(2, "little") + (80).to_bytes(2, "little") + b"\0" * 4
        fcntl = __import__("fcntl")
        fcntl.ioctl(slave_fd, termios.TIOCSWINSZ, size)
        shell_env = os.environ.copy()
        if env:
            shell_env.update(env)
        shell_env.setdefault("TERM", "xterm")
        self.process = subprocess.Popen(
            ["bash", "-i"], stdin=slave_fd, stdout=slave_fd, stderr=slave_fd,
            cwd=cwd, env=shell_env, close_fds=True, start_new_session=True,
        )
        os.close(slave_fd)
        os.set_blocking(self._master_fd, False)
        self._output = bytearray()
        self._lock = threading.Lock()
        self._closed = False
        self._reader = threading.Thread(target=self._read_loop, daemon=True)
        self._reader.start()

    def _read_loop(self) -> None:
        while not self._closed:
            try:
                readable, _, _ = select.select([self._master_fd], [], [], 0.05)
                if not readable:
                    continue
                data = os.read(self._master_fd, 65536)
                if data:
                    with self._lock:
                        self._output.extend(data)
                elif self.process.poll() is not None:
                    break
            except (OSError, ValueError):
                break

    def send_keystrokes(self, keystrokes: str, wait_sec: float = 0.0) -> None:
        if self._closed or self.process.poll() is not None:
            raise RuntimeError("terminal process is not running")
        data = keystrokes.encode("utf-8", errors="surrogateescape")
        view = memoryview(data)
        while view:
            try:
                count = os.write(self._master_fd, view)
                view = view[count:]
            except BlockingIOError:
                select.select([], [self._master_fd], [], 0.1)
        if wait_sec > 0:
            time.sleep(wait_sec)

    def get_output(self, clear: bool = True, encoding: str = "utf-8") -> str:
        """Return captured terminal output, optionally clearing the buffer."""
        with self._lock:
            data = bytes(self._output)
            if clear:
                self._output.clear()
        return data.decode(encoding, errors="replace")

    def read(self, wait_sec: float = 0.0) -> str:
        """Wait briefly for output, then return and clear the captured text."""
        if wait_sec > 0:
            time.sleep(wait_sec)
        return self.get_output()

    def close(self) -> None:
        """Terminate the shell and release the PTY."""
        if self._closed:
            return
        self._closed = True
        if self.process.poll() is None:
            try:
                os.killpg(self.process.pid, signal.SIGHUP)
                self.process.wait(timeout=1)
            except (ProcessLookupError, subprocess.TimeoutExpired):
                if self.process.poll() is None:
                    self.process.terminate()
                    try:
                        self.process.wait(timeout=1)
                    except subprocess.TimeoutExpired:
                        self.process.kill()
        try:
            os.close(self._master_fd)
        except OSError:
            pass
        self._reader.join(timeout=0.2)

    def __enter__(self) -> "HeadlessTerminal":
        return self

    def __exit__(self, *_exc) -> None:
        self.close()

    def __del__(self):
        try:
            self.close()
        except Exception:
            pass
